40	diff --git a/apps/server/src/DuelRoom.ts b/apps/server/src/DuelRoom.ts
41	new file mode 100644
42	index 0000000..d3efa37
43	--- /dev/null
44	+++ b/apps/server/src/DuelRoom.ts
45	@@ -0,0 +1,310 @@
46	+import { randomInt } from "node:crypto";
47	+import { performance } from "node:perf_hooks";
48	+import { ErrorCode, matchMaker, Room, ServerError, type AuthContext, type Client } from "colyseus";
49	+import {
50	+  createDuelOptionsSchema,
51	+  DUEL_CODE_REQUIRED_MESSAGE,
52	+  DUEL_COUNTDOWN_FRAMES,
53	+  DUEL_RECONNECT_SECONDS,
54	+  DUEL_ROOM,
55	+  DUEL_UNAVAILABLE_MESSAGE,
56	+  duelFullMessage,
57	+  DuelMessageType,
58	+  duelPracticeMessageSchema,
59	+  duelProbeReplySchema,
60	+  joinDuelOptionsSchema,
61	+  JoinRefusal,
62	+  MAX_INPUT_MESSAGES_PER_SECOND,
63	+  NO_SUCH_DUEL_MESSAGE,
64	+  PROTOCOL_VERSION,
65	+  type DuelEndReason,
66	+  type DuelProbe,
67	+  type DuelRoomPhase,
68	+  type DummyBehaviour,
69	+} from "@pirate-sea-race/protocol";
70	+import { createDuelState, defaultDuelConfig, duelInput, type DuelState, type PlayerIndex } from "@pirate-sea-race/simulation/duel";
71	+import { chooseInputDelay, DuelAuthority, linkStats, type AuthorityStats } from "@pirate-sea-race/simulation/netcode";
72	+import { admitSeat, authorizePrivateEntry, type AdmissionRules } from "./admission.js";
73	+import { DuelInputGate } from "./duelInputGate.js";
74	+import type { MatchMetadata } from "./MatchRoom.js";
75	+import { generateMatchCode } from "./matchCode.js";
76	+import { DuelRoomStateSchema, DuelSeatSchema } from "./schema.js";
77	+
78	+const STEPS_PER_SECOND = 60;
79	+/** The lobby state goes out at 20 Hz; the duel's frames travel as messages. */
80	+const PATCH_INTERVAL_MS = 1000 / 20;
81	+/** Round-trip probes: every 6 frames during the countdown (for the input delay), every 30 during the fight (the HUD). */
82	+const COUNTDOWN_PROBE_FRAMES = 6;
83	+const FIGHT_PROBE_FRAMES = 30;
84	+/** Round-trip samples kept per seat. */
85	+const PROBE_SAMPLES = 25;
86	+/** The input delay is chosen this many frames before the countdown ends, from the probes measured until then. */
87	+export const DELAY_DECISION_FRAMES = 30;
88	+
89	+/** A duel's admission: the `duel` listing, the duel option schemas and the duel refusal messages. */
90	+const DUEL_ADMISSION: AdmissionRules = {
91	+  roomName: DUEL_ROOM,
92	+  createSchema: createDuelOptionsSchema,
93	+  joinSchema: joinDuelOptionsSchema,
94	+  noSuchMessage: NO_SUCH_DUEL_MESSAGE,
95	+  codeRequiredMessage: DUEL_CODE_REQUIRED_MESSAGE,
96	+  fullMessage: duelFullMessage,
97	+};
98	+
99	+/** Checks a create or join request for a duel before matchmaking places it (see `authorizePrivateEntry`). */
100	+export function authorizeDuelEntry(options: unknown): Promise<true> {
101	+  return authorizePrivateEntry(options, DUEL_ADMISSION);
102	+}
103	+
104	+interface Seat {
105	+  readonly slot: PlayerIndex;
106	+  readonly gate: DuelInputGate;
107	+  readonly schema: DuelSeatSchema;
108	+  /** Probe ids in flight and when they were sent (performance.now()). */
109	+  readonly probes: Map<number, number>;
110	+  readonly rtts: number[];
111	+  nextProbe: number;
112	+}
113	+
114	+/** What the room reports to tests and diagnostics about a finished or running duel. */
115	+export interface DuelDiagnostics {
116	+  readonly phase: DuelRoomPhase;
117	+  readonly frame: number;
118	+  readonly inputDelay: number;
119	+  readonly authority: AuthorityStats;
120	+  /** Input messages the gate dropped, per slot and reason. */
121	+  readonly dropped: Record<string, DuelInputGate["dropped"]>;
122	+  readonly rttSamples: Record<string, readonly number[]>;
123	+}
124	+
125	+/**
126	+ * One standalone duel (the combat spike, §18 stage 1), privately admitted like a match: created with a one-time token,
127	+ * joined by its code, two players (or one against the server's dummy in practice). The countdown starts once every
128	+ * seat is taken; during it the room probes both round trips and, DELAY_DECISION_FRAMES before the end, chooses the
129	+ * shared input delay. It then steps `stepDuel` at 60 Hz through `DuelAuthority` (first copy of each frame's input
130	+ * wins, late input never rewrites a frame, the held input repeats for 250 ms and then neutral) and broadcasts a frame
131	+ * bundle every third frame. The step's result ends the duel, and so does a player absent past DUEL_RECONNECT_SECONDS.
132	+ */
133	+export class DuelRoom extends Room<{ state: DuelRoomStateSchema; metadata: MatchMetadata }> {
134	+  override maxClients = 2;
135	+  /** A flood ceiling: past it Colyseus disconnects the client. Excess input is dropped well below it, in the gate. */
136	+  override maxMessagesPerSecond = MAX_INPUT_MESSAGES_PER_SECOND * 4;
137	+  override patchRate = PATCH_INTERVAL_MS;
138	+  override state = new DuelRoomStateSchema();
139	+
140	+  private readonly config = defaultDuelConfig;
141	+  private authority!: DuelAuthority;
142	+  private readonly seats = new Map<string, Seat>();
143	+  private createToken: string | undefined;
144	+  private tick = 0;
145	+
146	+  static override async onAuth(_token: string, options: unknown, _context: AuthContext): Promise<true> {
147	+    return authorizeDuelEntry(options);
148	+  }
149	+
150	+  override async onCreate(options: unknown): Promise<void> {
151	+    const parsed = createDuelOptionsSchema.safeParse(options);
152	+    if (!parsed.success) throw new ServerError(ErrorCode.MATCHMAKE_INVALID_CRITERIA, DUEL_UNAVAILABLE_MESSAGE);
153	+    this.createToken = parsed.data.createToken;
154	+    const practice = parsed.data.practice === true;
155	+    this.maxClients = practice ? 1 : 2;
156	+    const code = await this.allocateCode();
157	+    const seed = randomInt(0, 2 ** 32);
158	+    this.authority = new DuelAuthority(this.config, createDuelState(this.config, { seed }));
159	+    this.state.code = code;
160	+    this.state.protocolVersion = PROTOCOL_VERSION;
161	+    this.state.practice = practice;
162	+    this.state.dummy = practice ? "idle" : "";
163	+    this.state.phase = "waiting";
164	+    this.state.countdown = DUEL_COUNTDOWN_FRAMES;
165	+    this.state.seed = seed;
166	+    this.state.winner = -1;
167	+    if (practice) this.authority.script(1, (state) => this.dummyInput(state));
168	+    // As for matches: the create request's token was copied into the listing; replacing the metadata drops it.
169	+    await this.setMatchmaking({ metadata: { code, custom: true } });
170	+
171	+    this.onMessage(DuelMessageType.Input, (client, message: unknown) => this.receiveInput(client, message));
172	+    this.onMessage(DuelMessageType.Probe, (client, message: unknown) => this.receiveProbeReply(client, message));
173	+    this.onMessage(DuelMessageType.Practice, (_client, message: unknown) => {
174	+      const request = duelPracticeMessageSchema.safeParse(message);
175	+      if (this.state.practice && request.success) this.state.dummy = request.data.dummy;
176	+    });
177	+    // Unknown message types are dropped, not answered: Colyseus would otherwise disconnect the sender.
178	+    this.onMessage("*", () => undefined);
179	+    this.setFixedTimestep(() => this.advance(), STEPS_PER_SECOND);
180	+  }
181	+
182	+  override onJoin(client: Client, options: unknown): void {
183	+    this.createToken = admitSeat(options, { code: this.state.code, createToken: this.createToken }, DUEL_ADMISSION);
184	+    const taken = new Set([...this.seats.values()].map((seat) => seat.slot));
185	+    const slot: PlayerIndex = taken.has(0) ? 1 : 0;
186	+    const schema = new DuelSeatSchema();
187	+    schema.sessionId = client.sessionId;
188	+    schema.slot = slot;
189	+    schema.connected = true;
190	+    this.state.seats.push(schema);
191	+    this.seats.set(client.sessionId, { slot, gate: new DuelInputGate(), schema, probes: new Map(), rtts: [], nextProbe: 1 });
192	+    if (this.state.phase === "waiting" && this.seats.size === this.maxClients) {
193	+      this.state.phase = "countdown";
194	+      void this.lock();
195	+    }
196	+  }
197	+
198	+  /** A player dropped without leaving: their seat is kept for DUEL_RECONNECT_SECONDS, then they forfeit (§12). */
199	+  override onDrop(client: Client): void {
200	+    const seat = this.seats.get(client.sessionId);
201	+    if (seat === undefined || this.state.phase === "over") return;
202	+    seat.schema.connected = false;
203	+    seat.probes.clear();
204	+    void this.allowReconnection(client, DUEL_RECONNECT_SECONDS).catch(() => undefined);
205	+  }
206	+
207	+  /** The same player is back: they continue from the authoritative state, which a snapshot bundle gives them. */
208	+  override onReconnect(client: Client): void {
209	+    const seat = this.seats.get(client.sessionId);
210	+    if (seat === undefined) return;
211	+    seat.schema.connected = true;
212	+    if (this.state.phase === "fighting" || this.state.phase === "over") client.send(DuelMessageType.Frames, this.authority.snapshotBundle());
213	+  }
214	+
215	+  /** A player left for good (quit, or absent past the reconnection window): before the countdown their seat frees up. */
216	+  override onLeave(client: Client): void {
217	+    const seat = this.seats.get(client.sessionId);
218	+    if (seat === undefined) return;
219	+    seat.schema.connected = false;
220	+    if (this.state.phase === "waiting") {
221	+      this.seats.delete(client.sessionId);
222	+      const index = this.state.seats.findIndex((entry) => entry.sessionId === client.sessionId);
223	+      if (index >= 0) this.state.seats.splice(index, 1);
224	+      return;
225	+    }
226	+    if (this.state.phase === "countdown" || this.state.phase === "fighting") {
227	+      const opponent: PlayerIndex = seat.slot === 0 ? 1 : 0;
228	+      this.finish(opponent, "forfeit", Math.max(0, this.authority.frame));
229	+    }
230	+  }
231	+
232	+  /** Inputs dropped per client and reason, for tests and diagnostics. */
233	+  droppedInputs(sessionId: string): DuelInputGate["dropped"] | undefined {
234	+    return this.seats.get(sessionId)?.gate.dropped;
235	+  }
236	+
237	+  /** The duel's counters, for tests and the harness. */
238	+  diagnostics(): DuelDiagnostics {
239	+    const bySlot = <T>(pick: (seat: Seat) => T) => Object.fromEntries([...this.seats.values()].map((seat) => [String(seat.slot), pick(seat)]));
240	+    return {
241	+      phase: this.state.phase as DuelRoomPhase,
242	+      frame: this.authority.frame,
243	+      inputDelay: this.state.inputDelay,
244	+      authority: structuredClone(this.authority.stats),
245	+      dropped: bySlot((seat) => ({ ...seat.gate.dropped })),
246	+      rttSamples: bySlot((seat) => [...seat.rtts]),
247	+    };
248	+  }
249	+
250	+  /** The authoritative duel state, for tests. */
251	+  get duelState(): DuelState {
252	+    return this.authority.state;
253	+  }
254	+
255	+  /** Every input pair applied so far as a replayable log, for tests. */
256	+  inputLog(): ReturnType<DuelAuthority["inputLog"]> {
257	+    return this.authority.inputLog();
258	+  }
259	+
260	+  /** The duel's frame on one timeline: negative during the countdown, then the frames stepped. */
261	+  private get serverFrame(): number {
262	+    return this.state.phase === "countdown" || this.state.phase === "waiting" ? -this.state.countdown : this.authority.frame;
263	+  }
264	+
265	+  private receiveInput(client: Client, message: unknown): void {
266	+    const seat = this.seats.get(client.sessionId);
267	+    if (seat === undefined || (this.state.phase !== "countdown" && this.state.phase !== "fighting")) return;
268	+    const input = seat.gate.receive(message, this.tick, this.serverFrame);
269	+    if (input === undefined || (this.state.practice && seat.slot !== 0)) return;
270	+    this.authority.receive(seat.slot, input.frame, input.inputs);
271	+  }
272	+
273	+  private receiveProbeReply(client: Client, message: unknown): void {
274	+    const seat = this.seats.get(client.sessionId);
275	+    const reply = duelProbeReplySchema.safeParse(message);
276	+    if (seat === undefined || !reply.success) return;
277	+    const sentAt = seat.probes.get(reply.data.id);
278	+    if (sentAt === undefined) return;
279	+    seat.probes.delete(reply.data.id);
280	+    seat.rtts.push(performance.now() - sentAt);
281	+    if (seat.rtts.length > PROBE_SAMPLES) seat.rtts.shift();
282	+    seat.schema.rtt = Math.round(linkStats(seat.rtts)!.rttMs);
283	+  }
284	+
285	+  private sendProbes(): void {
286	+    for (const client of this.clients) {
287	+      const seat = this.seats.get(client.sessionId);
288	+      if (seat === undefined || !seat.schema.connected) continue;
289	+      const id = seat.nextProbe++;
290	+      seat.probes.set(id, performance.now());
291	+      // Probes that never came back (a dropped connection) are forgotten after a few seconds' worth.
292	+      for (const old of seat.probes.keys()) if (old < id - 20) seat.probes.delete(old);
293	+      const probe: DuelProbe = { id, frame: this.serverFrame, rtt: seat.rtts.length === 0 ? 0 : linkStats(seat.rtts)!.rttMs };
294	+      client.send(DuelMessageType.Probe, probe);
295	+    }
296	+  }
297	+
298	+  private advance(): void {
299	+    this.tick++;
300	+    switch (this.state.phase) {
301	+      case "countdown":
302	+        this.state.countdown--;
303	+        if (this.state.countdown % COUNTDOWN_PROBE_FRAMES === 0) this.sendProbes();
304	+        if (this.state.countdown === DELAY_DECISION_FRAMES) {
305	+          this.state.inputDelay = chooseInputDelay([...this.seats.values()].map((seat) => linkStats(seat.rtts)));
306	+        }
307	+        if (this.state.countdown === 0) {
308	+          this.state.phase = "fighting";
309	+          this.broadcast(DuelMessageType.Frames, this.authority.snapshotBundle());
310	+        }
311	+        return;
312	+      case "fighting": {
313	+        const bundle = this.authority.step();
314	+        if (bundle !== undefined) this.broadcast(DuelMessageType.Frames, bundle);
315	+        if (this.authority.frame % FIGHT_PROBE_FRAMES === 0) this.sendProbes();
316	+        const result = this.authority.state.result;
317	+        if (result !== null) this.finish(result.winner, result.reason, result.frame);
318	+        return;
319	+      }
320	+      default:
321	+        return;
322	+    }
323	+  }
324	+
325	+  /** Ends the duel: the step's result, or a forfeit. Both players see it in the room state. */
326	+  private finish(winner: PlayerIndex | null, reason: DuelEndReason, frame: number): void {
327	+    if (this.state.phase === "over") return;
328	+    this.state.phase = "over";
329	+    this.state.winner = winner ?? -1;
330	+    this.state.reason = reason;
331	+    this.state.resultFrame = frame;
332	+  }
333	+
334	+  /**
335	+   * The practice dummy (§13's idle or defensive opponent): idle, or guarding. A guarding dummy holds back (away from
336	+   * player one) while player one strikes and while it is in blockstun, and stands still otherwise, so it neither
337	+   * backs out of range nor escapes a throw (throws beat guard).
338	+   */
339	+  private dummyInput(state: DuelState): number {
340	+    if ((this.state.dummy as DummyBehaviour) !== "guard") return 0;
341	+    const [player, dummy] = state.fighters;
342	+    const striking = player.action === "attack" && player.moveId !== this.config.moveset.commands.throw;
343	+    if (!striking && dummy.action !== "blockstun") return 0;
344	+    return duelInput(dummy.x >= player.x ? "right" : "left");
345	+  }
346	+
347	+  private async allocateCode(): Promise<string> {
348	+    for (let attempt = 0; attempt < 16; attempt++) {
349	+      const code = generateMatchCode();
350	+      const taken = await matchMaker.query({ name: this.roomName, code });
351	+      if (taken.length === 0) return code;
352	+    }
353	+    throw new ServerError(JoinRefusal.BadRequest, "Could not allocate a duel code");
354	+  }
355	+}
