497	+    throw new ServerError(JoinRefusal.MatchFull, rules.fullMessage(listing.maxClients));
498	+  }
499	+  return true;
500	+}
501	+
502	+/**
503	+ * The room's own admission check, which also covers `joinById` (no listing filter applies there): the one seat
504	+ * carrying the creator's token, then only seats carrying this room's code. Returns the creator's token still unspent
505	+ * (undefined once the creator's seat is taken); throwing refuses and frees the seat.
506	+ */
507	+export function admitSeat(options: unknown, room: { readonly code: string; readonly createToken: string | undefined }, rules: AdmissionRules): string | undefined {
508	+  const request = (options ?? {}) as { code?: unknown; createToken?: unknown };
509	+  if (request.createToken === undefined) {
510	+    if (request.code === room.code) return room.createToken;
511	+    if (request.code !== undefined) throw new ServerError(JoinRefusal.NoSuchMatch, rules.noSuchMessage);
512	+  } else if (request.code === undefined && room.createToken !== undefined && request.createToken === room.createToken) {
513	+    return undefined;
514	+  }
515	+  throw new ServerError(JoinRefusal.CodeRequired, rules.codeRequiredMessage);
516	+}
