591	@@ -0,0 +1,45 @@
592	+import { MAX_INPUT_MESSAGES_PER_SECOND, validateDuelInputMessage, type DuelInputMessage } from "@pirate-sea-race/protocol";
593	+import type { DropReason } from "./inputGate.js";
594	+
595	+const TICKS_PER_SECOND = 60;
596	+
597	+/**
598	+ * One duel client's input channel on the server, with the world input gate's limits unchanged: at most
599	+ * MAX_INPUT_MESSAGES_PER_SECOND messages per second of room time, MAX_INPUT_MESSAGE_BYTES each, sequence numbers
600	+ * strictly increasing, and no frame more than MAX_INPUT_LEAD_FRAMES past the server's. Every drop is counted.
601	+ * Accepted messages go on to the duel authority, which keeps the first copy of each frame's input.
602	+ */
603	+export class DuelInputGate {
604	+  private lastAcceptedSeq = 0;
605	+  private windowStart = Number.NEGATIVE_INFINITY;
606	+  private windowCount = 0;
607	+  readonly dropped: Record<DropReason, number> = {
608	+    "rate-limited": 0,
609	+    oversized: 0,
610	+    malformed: 0,
611	+    "stale-sequence": 0,
612	+    "future-frame": 0,
613	+  };
614	+
615	+  /**
616	+   * Takes one untrusted message at room tick `tick` (60 a second, for the rate window) when the duel's current frame
617	+   * is `serverFrame` (negative during the countdown). Returns the accepted message, or undefined when it was dropped.
618	+   */
619	+  receive(message: unknown, tick: number, serverFrame: number): DuelInputMessage | undefined {
620	+    if (tick - this.windowStart >= TICKS_PER_SECOND) {
621	+      this.windowStart = tick;
622	+      this.windowCount = 0;
623	+    }
624	+    if (++this.windowCount > MAX_INPUT_MESSAGES_PER_SECOND) {
625	+      this.dropped["rate-limited"]++;
626	+      return undefined;
627	+    }
628	+    const result = validateDuelInputMessage(message, { lastAcceptedSeq: this.lastAcceptedSeq, serverFrame });
629	+    if (!result.ok) {
630	+      this.dropped[result.reason]++;
631	+      return undefined;
632	+    }
633	+    this.lastAcceptedSeq = result.input.seq;
634	+    return result.input;
635	+  }
636	+}
