1	import { hashState } from "../hash.js";
2	import { sanitizeDuelInput, type DuelInputs } from "../duel/input.js";
3	import { restoreDuel } from "../duel/snapshot.js";
4	import type { DuelConfig, DuelState, PlayerIndex } from "../duel/state.js";
5	import { stepDuel } from "../duel/step.js";
6	import { DuelEventFeed, type DuelFeedEvent } from "./events.js";
7	
8	/** Two seconds of 60 Hz frames: how far the client predicts past its last confirmed frame, and the history it keeps. */
9	export const HISTORY_FRAMES = 120;
10	
11	/**
12	 * The server repeats a player's last input for at most this many frames (250 ms) before it substitutes neutral (§15);
13	 * the client predicts its own missing inputs the same way.
14	 */
15	export const HELD_INPUT_FRAMES = 15;
16	
17	/**
18	 * What the server confirmed (the protocol's frame bundle, structurally): the input pairs it applied for the frames
19	 * ending with `frame`, oldest first, and either the state after `frame` as a snapshot or its `hashState`.
20	 */
21	export interface ConfirmedFrames {
22	  readonly frame: number;
23	  readonly inputs: readonly (readonly [number, number])[];
24	  /** Bit `2k + p`: player `p`'s input for the k-th frame was substituted by the server. */
25	  readonly substituted?: number;
26	  readonly snapshot?: unknown;
27	  readonly hash?: string;
28	}
29	
30	export interface DuelNetStats {
31	  /** Restores caused by a confirmed input that differed from the one the prediction used. */
32	  corrections: number;
33	  /** Frames stepped again by those corrections and by snapshot restores. */
34	  replayedFrames: number;
35	  /** The longest single replay, in frames. */
36	  deepestReplay: number;
37	  /** Server hashes compared with the client's own state at the same frame. */
38	  hashChecks: number;
39	  /** Comparisons that differed. */
40	  desyncs: number;
41	  /** Times the timeline was restored from a server snapshot (after a desync, a gap or a resync). */
42	  snapshotRestores: number;
43	  /** Frames whose input the server substituted, per player. */
44	  substitutedFrames: [number, number];
45	}
46	
47	interface Check {
48	  readonly hash: string;
49	  readonly snapshot: unknown;
50	}
51	
52	const samePair = (a: DuelInputs | undefined, b: DuelInputs | undefined) => a !== undefined && b !== undefined && a[0] === b[0] && a[1] === b[1];
53	
54	/**
55	 * The client's side of §15's server-authoritative prediction and rollback, for one duel and one local player. It is
56	 * pure: it keeps plain duel states and inputs, steps them with the shared `stepDuel`, and never reads a clock.
57	 *
58	 * - Prediction: each frame past the last confirmed one is stepped with the local player's own input for it (as sent;
59	 *   a missing one repeats the last for up to HELD_INPUT_FRAMES, like the server) and the opponent's last confirmed
60	 *   input repeated.
61	 * - Confirmation: `applyBundle` records the input pairs the server applied. When one differs from the pair a frame
62	 *   was predicted with, the last confirmed state is restored and every frame since is stepped again: confirmed frames
63	 *   with the server's inputs (never the client's own record of what it sent), later frames with local and predicted
64	 *   inputs. Each such restore counts as a correction.
65	 * - Desync detection: at every bundle's frame, once the client has stepped it from confirmed inputs, the hash of its
66	 *   own state is compared with the server's, before anything is restored. A mismatch is counted, and the server's
67	 *   snapshot (every second bundle) replaces the client's state.
68	 * - A gap in the confirmed frames (a rejoin) waits for the next snapshot and restarts from it.
69	 *
70	 * States, used inputs and local inputs are kept for about HISTORY_FRAMES; prediction stops that far past the last
71	 * confirmed frame until the server is heard from again.
72	 */
73	export class DuelRollback {
74	  readonly stats: DuelNetStats = {
75	    corrections: 0,
76	    replayedFrames: 0,
77	    deepestReplay: 0,
78	    hashChecks: 0,
79	    desyncs: 0,
80	    snapshotRestores: 0,
81	    substitutedFrames: [0, 0],
82	  };
83	
84	  private readonly states = new Map<number, DuelState>();
85	  private readonly used = new Map<number, DuelInputs>();
86	  private readonly confirmed = new Map<number, DuelInputs>();
87	  private readonly local = new Map<number, number>();
88	  private readonly checks = new Map<number, Check>();
89	  private readonly feed = new DuelEventFeed();
90	  private head: number;
91	  private confirmedThrough: number;
92	  /** The newest frame the server has confirmed inputs for (possibly ahead of `head`). */
93	  private receivedThrough: number;
94	  private lastConfirmed: DuelInputs = [0, 0];
95	  private latestSnapshot: { frame: number; snapshot: unknown } | undefined;
96	  private awaitingSnapshot = false;
97	
98	  constructor(
99	    private readonly config: DuelConfig,
100	    readonly player: PlayerIndex,
101	    initial: DuelState,
102	    private readonly historyFrames = HISTORY_FRAMES,
103	  ) {
104	    this.head = initial.frame;
105	    this.confirmedThrough = initial.frame;
106	    this.receivedThrough = initial.frame;
107	    this.states.set(initial.frame, initial);
108	  }
109	
110	  /** The newest simulated frame (predicted past `confirmedFrame`). */
111	  get frame(): number {
112	    return this.head;
113	  }
114	
115	  /** The predicted state at `frame`: what the view draws. */
116	  get state(): DuelState {
117	    return this.states.get(this.head)!;
118	  }
119	
120	  /** The newest frame stepped from confirmed inputs only. */
121	  get confirmedFrame(): number {
122	    return this.confirmedThrough;
123	  }
124	
125	  /** The state at `confirmedFrame`: the server's, unless a desync is waiting for its snapshot. */
126	  get confirmedState(): DuelState {
127	    return this.states.get(this.confirmedThrough)!;
128	  }
129	
130	  /** True while a gap in the server's frames waits for a snapshot to restart from. */
131	  get waitingForSnapshot(): boolean {
132	    return this.awaitingSnapshot;
133	  }
134	
135	  /** Whether `step` can go on: prediction stops HISTORY_FRAMES past the last confirmed frame. */
136	  get canStep(): boolean {
137	    return this.head < this.confirmedThrough + this.historyFrames;
138	  }
139	
140	  /** The state stepped for `frame` on the current timeline, while it is in the history. */
141	  stateAt(frame: number): DuelState | undefined {
142	    return this.states.get(frame);
143	  }
144	
145	  /** The newest snapshot the server sent, if any. */
146	  get snapshot(): { readonly frame: number; readonly snapshot: unknown } | undefined {
147	    return this.latestSnapshot;
148	  }
149	
150	  /** The local player's input for `frame`, as the caller tagged it (after the input delay). */
151	  setLocalInput(frame: number, bits: number): void {
152	    this.local.set(frame, sanitizeDuelInput(bits));
153	  }
154	
155	  localInput(frame: number): number | undefined {
156	    return this.local.get(frame);
157	  }
158	
159	  /** The input pair the frame was (or will be) stepped with: the server's when confirmed, a prediction otherwise. */
160	  inputsFor(frame: number): DuelInputs {
161	    const confirmed = this.confirmed.get(frame);
162	    if (confirmed !== undefined) return confirmed;
163	    let own = 0;
164	    for (let back = frame; back >= frame - HELD_INPUT_FRAMES; back--) {
165	      const bits = this.local.get(back);
166	      if (bits !== undefined) {
167	        own = bits;
168	        break;
169	      }
170	    }
171	    const opponent = this.lastConfirmed[this.player === 0 ? 1 : 0];
172	    return this.player === 0 ? [own, opponent] : [opponent, own];
173	  }
174	
175	  /** Steps one frame past `frame`. False when prediction has reached its limit. */
176	  step(): boolean {
177	    if (!this.canStep) return false;
178	    this.simulate(this.head + 1);
179	    this.head++;
180	    this.fold();
181	    return true;
182	  }
183	
184	  /** Steps until `frame` (or the prediction limit); returns the frames stepped. */
185	  stepTo(frame: number): number {
186	    let stepped = 0;
187	    while (this.head < frame && this.step()) stepped++;
188	    return stepped;
189	  }
190	
191	  /** Takes one frame bundle from the server. */
192	  applyBundle(bundle: ConfirmedFrames): void {
193	    const first = bundle.frame - bundle.inputs.length + 1;
194	    const serverHash = bundle.hash ?? (bundle.snapshot === undefined ? undefined : hashState(bundle.snapshot));
195	    if (bundle.snapshot !== undefined) this.latestSnapshot = { frame: bundle.frame, snapshot: bundle.snapshot };
196	
197	    if (this.awaitingSnapshot || first > this.receivedThrough + 1) {
198	      // Frames are missing (the connection was replaced): nothing can be confirmed until a snapshot restarts it.
199	      this.awaitingSnapshot = true;
200	      if (bundle.snapshot !== undefined) this.restartFrom(bundle.frame, bundle.snapshot, bundle.inputs.at(-1));
201	      return;
202	    }
203	
204	    bundle.inputs.forEach((pair, index) => {
205	      const frame = first + index;
206	      for (const player of [0, 1] as const) if (((bundle.substituted ?? 0) >> (2 * index + player)) & 1) this.stats.substitutedFrames[player]++;
207	      if (frame <= this.receivedThrough) return;
208	      const clean: DuelInputs = [sanitizeDuelInput(pair[0]), sanitizeDuelInput(pair[1])];
209	      this.confirmed.set(frame, clean);
210	      this.receivedThrough = frame;
211	      this.lastConfirmed = clean;
212	    });
213	
214	    // The earliest simulated frame whose confirmed inputs differ from the ones it was predicted with.
215	    for (let frame = this.confirmedThrough + 1; frame <= Math.min(this.head, this.receivedThrough); frame++) {
216	      if (!samePair(this.used.get(frame), this.confirmed.get(frame))) {
217	        this.stats.corrections++;
218	        this.replayFrom(this.confirmedThrough);
219	        break;
220	      }
221	    }
222	
223	    if (serverHash !== undefined && bundle.frame >= this.confirmedThrough - this.historyFrames) {
224	      this.checks.set(bundle.frame, { hash: serverHash, snapshot: bundle.snapshot });
225	      // A check for a frame already confirmed (a snapshot sent on joining) runs now; the others as frames confirm.
226	      if (bundle.frame < this.confirmedThrough) this.runCheck(bundle.frame);
227	    }
228	    this.fold();
229	  }
230	
231	  /**
232	   * Restarts from the newest server snapshot (after a stall, or a hidden tab), then steps back up to the frame the
233	   * client had reached. False when no snapshot has arrived yet.
234	   */
235	  resync(): boolean {
236	    const latest = this.latestSnapshot;
237	    if (latest === undefined) return false;
238	    this.restartFrom(latest.frame, latest.snapshot, undefined);
239	    return true;
240	  }
241	
242	  /** The events of newly simulated frames, each reported once whatever rollback re-simulates. */
243	  drainEvents(): DuelFeedEvent[] {
244	    return this.feed.drain();
245	  }
246	
247	  /** Steps frame `frame` from the stored state before it, with `inputsFor(frame)`. */
248	  private simulate(frame: number): void {
249	    const inputs = this.inputsFor(frame);
250	    const state = stepDuel(this.config, this.states.get(frame - 1)!, inputs);
251	    this.states.set(frame, state);
252	    this.used.set(frame, inputs);
253	    this.feed.observe(state);
254	  }
255	
256	  /** Steps every frame after `from` up to the head again, from the stored state at `from`. */
257	  private replayFrom(from: number): void {
258	    const frames = this.head - from;
259	    for (let frame = from + 1; frame <= this.head; frame++) this.simulate(frame);
260	    this.stats.replayedFrames += frames;
261	    this.stats.deepestReplay = Math.max(this.stats.deepestReplay, frames);
262	  }
263	
264	  /**
265	   * Advances the confirmed frame over every simulated frame that was stepped with confirmed inputs, comparing the
266	   * client's own state with the server's hash wherever one is due, before any snapshot replaces it.
267	   */
268	  private fold(): void {
269	    for (;;) {
270	      this.runCheck(this.confirmedThrough);
271	      const next = this.confirmedThrough + 1;
272	      if (next > this.head || !samePair(this.used.get(next), this.confirmed.get(next))) break;
273	      this.confirmedThrough = next;
274	    }
275	    this.prune();
276	  }
277	
278	  private runCheck(frame: number): void {
279	    const check = this.checks.get(frame);
280	    const own = this.states.get(frame);
281	    if (check === undefined || own === undefined) return;
282	    this.checks.delete(frame);
283	    this.stats.hashChecks++;
284	    if (hashState(own) === check.hash) return;
285	    this.stats.desyncs++;
286	    if (check.snapshot === undefined) return;
287	    // The server's state is the authority: restart from it and predict forward again.
288	    this.states.set(frame, restoreDuel(this.config, check.snapshot));
289	    this.stats.snapshotRestores++;
290	    this.replayFrom(frame);
291	  }
292	
293	  /** Discards the timeline and restarts from a server snapshot at `frame`, keeping the local inputs. */
294	  private restartFrom(frame: number, snapshot: unknown, lastPair: readonly [number, number] | undefined): void {
295	    const restored = restoreDuel(this.config, snapshot);
296	    const previousHead = this.head;
297	    this.states.clear();
298	    this.used.clear();
299	    // Confirmed inputs after the snapshot stay only while they follow it without a hole.
300	    let next = frame + 1;
301	    while (this.confirmed.has(next)) next++;
302	    for (const key of [...this.confirmed.keys()]) if (key <= frame || key >= next) this.confirmed.delete(key);
303	    for (const key of [...this.checks.keys()]) if (key <= frame) this.checks.delete(key);
304	    this.states.set(frame, restored);
305	    this.head = frame;
306	    this.confirmedThrough = frame;
307	    this.receivedThrough = next - 1;
308	    if (lastPair !== undefined) this.lastConfirmed = [sanitizeDuelInput(lastPair[0]), sanitizeDuelInput(lastPair[1])];
309	    this.awaitingSnapshot = false;
310	    this.stats.snapshotRestores++;
311	    const target = Math.min(previousHead, frame + this.historyFrames);
312	    const stepped = this.stepTo(target);
313	    this.stats.replayedFrames += stepped;
314	    this.stats.deepestReplay = Math.max(this.stats.deepestReplay, stepped);
315	  }
316	
317	  private prune(): void {
