1	import {
2	  duelFrameBundleSchema,
3	  DuelMessageType,
4	  duelProbeSchema,
5	  type DuelPracticeMessage,
6	  type DuelProbeReply,
7	  type DuelRoomPhase,
8	  type DummyBehaviour,
9	} from "@pirate-sea-race/protocol";
10	import { createDuelState, defaultDuelConfig, type DuelState, type PlayerIndex } from "@pirate-sea-race/simulation/duel";
11	import { DuelClientSession, type DuelFeedEvent } from "@pirate-sea-race/simulation/netcode";
12	import type { ArenaSource } from "./arenaScene.js";
13	import type { DuelRoom } from "./duelConnection.js";
14	import { renderDuelHud, resultText, type DuelConnectionStatus } from "./duelHud.js";
15	import { DuelKeyboard } from "./duelKeyboard.js";
16	
17	/** The client ticks this often: far finer than a frame, and independent of the display's refresh rate. */
18	const TICK_MS = 4;
19	/** The HUD is redrawn this often. */
20	const HUD_MS = 50;
21	
22	const { rules } = defaultDuelConfig.moveset;
23	
24	/**
25	 * One browser's duel: the room's messages feed a `DuelClientSession` (the same rollback core the headless test
26	 * client runs), a 4 ms timer ticks it with the keyboard's input and sends what it returns, the arena draws the
27	 * predicted state, and the HUD shows the confirmed one. `window.__duel` exposes read-only diagnostics for tests.
28	 */
29	export class DuelClient implements ArenaSource {
30	  private session: DuelClientSession | undefined;
31	  private status: DuelConnectionStatus = "connected";
32	  private boxes = false;
33	  private readonly keyboard: DuelKeyboard;
34	  private readonly timers: number[] = [];
35	  private readonly pendingEvents: DuelFeedEvent[] = [];
36	
37	  constructor(
38	    private readonly room: DuelRoom,
39	    private readonly hud: HTMLElement,
40	  ) {
41	    this.keyboard = new DuelKeyboard(window);
42	    room.onMessage(DuelMessageType.Probe, (message: unknown) => {
43	      const probe = duelProbeSchema.safeParse(message);
44	      if (!probe.success) return;
45	      room.send(DuelMessageType.Probe, { id: probe.data.id } satisfies DuelProbeReply);
46	      this.ensureSession()?.receiveProbe(probe.data, performance.now());
47	    });
48	    room.onMessage(DuelMessageType.Frames, (message: unknown) => {
49	      const bundle = duelFrameBundleSchema.safeParse(message);
50	      if (bundle.success) this.ensureSession()?.receiveBundle(bundle.data, performance.now());
51	    });
52	    room.onDrop(() => {
53	      this.status = "reconnecting";
54	    });
55	    room.onReconnect(() => {
56	      this.status = "connected";
57	    });
58	    room.onLeave(() => {
59	      this.status = "disconnected";
60	      this.renderHud();
61	      for (const timer of this.timers) window.clearInterval(timer);
62	    });
63	    this.timers.push(window.setInterval(() => this.tick(), TICK_MS));
64	    this.timers.push(window.setInterval(() => this.renderHud(), HUD_MS));
65	    (window as unknown as { __duel: unknown }).__duel = {
66	      stats: () => this.session?.stats,
67	      frame: () => this.session?.frame,
68	      confirmedFrame: () => this.session?.rollback.confirmedFrame,
69	      lastTaggedFrame: () => this.session?.lastTaggedFrame,
70	      /** The input bits this client tagged for frames `from` to `to` (0 where none was). */
71	      taggedInputs: (from: number, to: number) =>
72	        Array.from({ length: Math.max(0, to - from + 1) }, (_, index) => this.session?.rollback.localInput(from + index) ?? 0),
73	    };
74	  }
75	
76	  /** The developer toggle for hurtboxes and hitboxes. */
77	  setShowBoxes(show: boolean): void {
78	    this.boxes = show;
79	  }
80	
81	  /** Practice rooms: the dummy idles or guards. */
82	  setDummy(dummy: DummyBehaviour): void {
83	    this.room.send(DuelMessageType.Practice, { dummy } satisfies DuelPracticeMessage);
84	  }
85	
86	  state(): DuelState | undefined {
87	    return this.session?.state;
88	  }
89	
90	  drainEvents(): DuelFeedEvent[] {
91	    this.collectEvents();
92	    return this.pendingEvents.splice(0);
93	  }
94	
95	  stateAt(frame: number): DuelState | undefined {
96	    return this.session?.rollback.stateAt(frame);
97	  }
98	
99	  showBoxes(): boolean {
100	    return this.boxes;
101	  }
102	
103	  banner(): string {
104	    const state = this.room.state;
105	    if (state === undefined) return "";
106	    if (state.phase === "waiting") return state.practice ? "" : "Waiting for an opponent";
107	    if (state.phase === "countdown") return String(Math.max(1, Math.ceil(state.countdown / 60)));
108	    if (state.phase === "over") return resultText(state.winner, state.reason);
109	    return (this.session?.frame ?? 0) < 45 ? "FIGHT" : "";
110	  }
111	
112	  private get self(): PlayerIndex | undefined {
113	    const seat = this.room.state?.seats?.find((entry) => entry.sessionId === this.room.sessionId);
114	    return seat === undefined ? undefined : (seat.slot as PlayerIndex);
115	  }
116	
117	  private ensureSession(): DuelClientSession | undefined {
118	    if (this.session !== undefined) return this.session;
119	    const self = this.self;
120	    const seed = this.room.state?.seed;
121	    if (self === undefined || seed === undefined) return undefined;
122	    this.session = new DuelClientSession({ config: defaultDuelConfig, player: self, initial: createDuelState(defaultDuelConfig, { seed }) });
123	    return this.session;
124	  }
125	
126	  private tick(): void {
127	    const session = this.ensureSession();
128	    // Once the result is in, nothing the player presses matters any more.
129	    if (session === undefined || this.room.state?.phase === "over") return;
130	    const delay = this.room.state?.inputDelay ?? 0;
131	    if (delay > 0) session.inputDelay = delay;
132	    const tagged = session.lastTaggedFrame;
133	    const message = session.tick(performance.now(), this.keyboard.bits());
134	    if (session.lastTaggedFrame > tagged) this.keyboard.framesTagged();
135	    if (message !== undefined) this.room.send(DuelMessageType.Input, message);
136	    this.collectEvents();
137	  }
138	
139	  /** Events are drained every tick, so none is lost while the arena is not drawing (a hidden tab). */
140	  private collectEvents(): void {
141	    const fresh = this.session?.drainEvents() ?? [];
142	    this.pendingEvents.push(...fresh);
143	    if (this.pendingEvents.length > 32) this.pendingEvents.splice(0, this.pendingEvents.length - 32);
144	  }
145	
146	  private renderHud(): void {
147	    const state = this.room.state;
148	    const self = this.self;
149	    if (state === undefined || self === undefined) return;
150	    const session = this.ensureSession();
151	    const connected = [0, 1].map((slot) => state.seats.find((seat) => seat.slot === slot)?.connected ?? false) as [boolean, boolean];
152	    renderDuelHud(this.hud, {
153	      code: state.code,
154	      practice: state.practice,
155	      phase: state.phase as DuelRoomPhase,
156	      status: this.status,
157	      self,
158	      countdown: state.countdown,
159	      connected,
160	      confirmed: session?.confirmedState ?? createDuelState(defaultDuelConfig, { seed: state.seed }),
161	      maxHealth: rules.maxHealth,
162	      maxStamina: rules.maxStamina,
163	      roundFrames: rules.roundFrames,
164	      overtimeFrames: rules.overtimeFrames,
165	      rttMs: session?.rttMs ?? 0,
166	      inputDelay: state.inputDelay,
167	      corrections: session?.stats.corrections ?? 0,
168	      result: state.phase === "over" ? { winner: state.winner, reason: state.reason } : undefined,
169	    });
170	  }
171	}
